draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // brain
  ctx.fillStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50 * Math.sin(t), H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120);
  ctx.lineTo(W/2, H/2 + 200); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2 - 30, H/2 + 180); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2 + 30, H/2 + 180); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 - 20, H/2 + 250); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 + 20, H/2 + 250); // leg
  ctx.stroke();

  ctx.restore();
}
